detaileddescription.para:
Example of a TimeoutWithPredicate: boolrun=true;
sf::Sftp::TimeoutWithPredicatetimeout([&run]{returnrun;},sf::milliseconds(1));
 When passed to an operation, the above TimeoutWithPredicate object will keep the operation running as long as run is true. The condition is checked every 1 millisecond. As soon as run is set to false the operation will terminate with a Timeout result.

Usage example: //CreateanewSFTPclient
sf::Sftpsftp;

//Gettheaddressoftheserver
constautoaddresses=sf::Dns::resolve("sftp.myserver.com");

//Checkifwehaveavalidaddress
if(!addresses.has_value()||addresses->empty())
{
//Handlenovalidaddress...
}

//Connecttotheserver
sf::Sftp::Resultresult=sftp.connect(addresses->front());
if(result.isOk())
std::cout<<"Connected"<<std::endl;

//Checksessioninformationandverifyserver
std::optional<sf::Sftp::SessionInfo>info=sftp.getSessionInfo();
if(info->hostKey.sha256!=expectedSha256)
{
std::cout<<"Serveruntrusted"<<std::endl;
//Handleuntrustedserver
}

//Login
result=sftp.login("sftpuser","dF6Zm89D");
if(result.isOk())
std::cout<<"Loggedin"<<std::endl;

//Printtheworkingdirectory
sf::Sftp::PathResultdirectory=sftp.getWorkingDirectory();
if(directory.isOk())
std::cout<<"Workingdirectory:"<<directory.getPath().string()<<std::endl;

//Createanewdirectory
result=sftp.createDirectory("files");
if(result.isOk())
std::cout<<"Creatednewdirectory"<<std::endl;

//Uploadatextfiletothisnewdirectory
result=sftp.upload("files/newfile.txt",[](void*data,std::size_t&size)
{
//Inyourowncode,ensuresizeisbigenoughtostoreyourdata
//Weskipthecheckhereforsimplicity
std::memcpy(data,"HelloWorld",11);
size=11;
returnfalse;//Endtransferafterthisblock
});
if(response.isOk())
std::cout<<"Fileuploaded"<<std::endl;

//Renamefile
result=sftp.rename("files/newfile.txt","files/newfile2.txt");
if(result.isOk())
std::cout<<"Renamedfile"<<std::endl;

//Downloadatextfilefromthisnewdirectory
std::stringtext;
result=sftp.download("files/newfile2.txt",[&text](constvoid*data,std::size_tsize)
{
text.append(static_cast<constchar*>(data),size);
returntrue;//Continueuntilalldatareceived
});
if(response.isOk())
std::cout<<"Filedownloaded:"<<text<<std::endl;

//Deletefile
result=sftp.deleteFile("files/newfile2.txt");
if(result.isOk())
std::cout<<"Deletedfile"<<std::endl;

//Deletedirectory
result=sftp.deleteDirectory("files");
if(result.isOk())
std::cout<<"Deleteddirectory"<<std::endl;

//Disconnectfromtheserver(optional)
result=sftp.disconnect();
if(result.isOk())
std::cout<<"Disconnectedsuccessfully"<<std::endl;
